// Facade over the native module (`native.cjs`, generated by `napi build`). It gives the
// native errors one class, `BothyError`, whose `kind` is the engine's error kind.
import { createRequire } from "node:module";

const native = createRequire(import.meta.url)("./native.cjs");

const KINDS = new Set([
  "Offline", "AuthRequired", "RateLimited", "QuotaExceeded", "RemoteInconsistent",
  "FormatTooNew", "SchemaTooNew", "WrongPassword", "KeyRequired", "Corrupt",
  "DatabaseLocked", "InvalidInput", "Internal",
]);

export class BothyError extends Error {
  constructor(kind, message) {
    super(message);
    this.name = "BothyError";
    this.kind = kind;
  }
}

const ARGUMENT_CODES = new Set([
  "InvalidArg", "StringExpected", "NumberExpected", "BooleanExpected",
  "ObjectExpected", "ArrayExpected", "FunctionExpected", "BigintExpected",
]);

/**
 * Native errors carry the kind as a `bothy:<Kind>:<message>` prefix. A napi argument error is
 * `InvalidInput`; any other native failure is `Internal`. Anything else is the caller's own
 * exception (a throwing getter or Proxy trap) and passes through untouched.
 */
function translate(err) {
  if (err instanceof BothyError) return err;
  const message = err && typeof err.message === "string" ? err.message : "";
  const m = err && err.code === "GenericFailure" ? /^bothy:([A-Za-z]+):([\s\S]*)$/.exec(message) : null;
  if (m && KINDS.has(m[1])) return new BothyError(m[1], m[2]);
  if (err && ARGUMENT_CODES.has(err.code)) return new BothyError("InvalidInput", message);
  if (err && err.code === "GenericFailure") return new BothyError("Internal", message);
  return err;
}

/** Runs a native call; sync throws (argument conversion) and rejections both become BothyError. */
async function call(run) {
  try {
    return await run();
  } catch (err) {
    throw translate(err);
  }
}

export class FolderRemote extends native.FolderRemote {
  constructor(path) {
    try {
      super(path);
    } catch (err) {
      throw translate(err);
    }
  }
}

export class Collection {
  #native;

  constructor(nativeCollection) {
    this.#native = nativeCollection;
  }

  put(id, doc) {
    return call(() => this.#native.put(id, doc));
  }

  get(id) {
    return call(() => this.#native.get(id));
  }

  patch(id, fields, unset) {
    if (unset !== undefined && !Array.isArray(unset)) {
      return Promise.reject(new BothyError("InvalidInput", "unset must be an array of field names"));
    }
    return call(() => this.#native.patch(id, fields, unset));
  }

  delete(id) {
    return call(() => this.#native.delete(id));
  }

  list(options) {
    return call(() => {
      if (options !== undefined && options !== null && typeof options !== "object") {
        throw new BothyError("InvalidInput", "list needs an options object");
      }
      const { limit, after } = options ?? {};
      if (limit !== undefined && !(Number.isSafeInteger(limit) && limit >= 0)) {
        throw new BothyError("InvalidInput", "limit must be a non-negative integer");
      }
      return this.#native.list(limit === undefined ? null : Math.min(limit, 0xffff_ffff), after ?? null);
    });
  }
}

export class Database {
  #native;

  constructor(nativeDb) {
    this.#native = nativeDb;
  }

  static async open(options) {
    if (options === null || typeof options !== "object") {
      throw new BothyError("InvalidInput", "open needs an options object");
    }
    const { path, appId, remote, deviceName } = options;
    if (!(remote instanceof FolderRemote)) {
      throw new BothyError("InvalidInput", "remote must be a FolderRemote");
    }
    const db = await call(() => native.openDatabase(path, appId, remote.path, deviceName ?? null));
    return new Database(db);
  }

  collection(name) {
    try {
      return new Collection(this.#native.collection(name));
    } catch (err) {
      throw translate(err);
    }
  }

  collections() {
    return call(() => this.#native.collections());
  }

  initOrJoin() {
    return call(() => this.#native.initOrJoin());
  }

  sync() {
    return call(() => this.#native.sync());
  }

  close() {
    return call(() => this.#native.close());
  }
}

export const { version } = native;
